import { describe, expect, it } from 'vitest';
import { pyRound } from '../../src/core/pyround';
import { clampCore } from '../../src/core/recipe';

describe('pyRound', () => {
  // Generated by running Python round(v, n) in backend/.venv
  const one: Array<[number, number]> = [[0.25, 0.2], [12.25, 12.2], [-0.25, -0.2], [2.5, 2.5], [0.15, 0.1], [2.675, 2.7], [1.45, 1.4], [0.35, 0.3], [12.44, 12.4], [12.45, 12.4], [-12.35, -12.3], [511.95, 511.9], [0.125, 0.1], [0.375, 0.4], [0.95, 0.9], [4.2, 4.2], [1.005, 1.0], [2.345, 2.3]];
  const two: Array<[number, number]> = [[0.25, 0.25], [12.25, 12.25], [-0.25, -0.25], [2.5, 2.5], [0.15, 0.15], [2.675, 2.67], [1.45, 1.45], [0.35, 0.35], [12.44, 12.44], [12.45, 12.45], [-12.35, -12.35], [511.95, 511.95], [0.125, 0.12], [0.375, 0.38], [0.95, 0.95], [4.2, 4.2], [1.005, 1.0], [2.345, 2.35]];
  it.each(one)('round(%d, 1) = %d', (v, e) => expect(pyRound(v, 1)).toBe(e));
  it.each(two)('round(%d, 2) = %d', (v, e) => expect(pyRound(v, 2)).toBe(e));
  it('clampCore clamps and rounds half-even', () => {
    expect(clampCore(0.25)).toBe(0.2);
    expect(clampCore(9999)).toBe(512);
  });
});
